using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using System.Threading.Tasks;
namespace TriReviewBridge {
 public sealed class DraftFileStore:IDisposable {
  string Folder,Prefix;byte[] Entropy;FileStream Lease;public string FilePath{get;private set;}
  static void NoReparse(string path,string root){var current=new DirectoryInfo(path);while(current!=null&&current.FullName.Length>=root.Length){if(current.Exists&&(current.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("草稿目录不能通过链接跳转。");if(String.Equals(current.FullName,root,StringComparison.OrdinalIgnoreCase))break;current=current.Parent;}}
  public DraftFileStore(string root,string config,string profile,bool isolate=false){Folder=isolate?Path.Combine(Path.GetDirectoryName(config),"desktop-drafts"):Path.Combine(root,"data","desktop-drafts");NoReparse(Folder,root);Directory.CreateDirectory(Folder);using(var hash=SHA256.Create())Entropy=hash.ComputeHash(Encoding.UTF8.GetBytes(Path.GetFullPath(config).ToLowerInvariant()));Prefix=BitConverter.ToString(Entropy).Replace("-","").Substring(0,24)+"-";if(String.IsNullOrEmpty(profile))profile="main";if(!System.Text.RegularExpressions.Regex.IsMatch(profile,"^[a-zA-Z0-9_-]{1,80}$"))throw new IOException("无效草稿档案名称。");for(int n=0;n<3;n++){FilePath=Path.Combine(Folder,Prefix+profile+".bin");try{Lease=new FileStream(FilePath+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);break;}catch(IOException){profile="window-"+Guid.NewGuid().ToString("N");}}if(Lease==null)throw new IOException("不能独占草稿档案，不覆盖其他窗口。");}
  public Dictionary<string,LocalDraft> Load(string path=null){path=path??FilePath;if(!File.Exists(path))return new Dictionary<string,LocalDraft>();if(!String.Equals(Path.GetDirectoryName(path),Folder,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(path).StartsWith(Prefix)||!path.EndsWith(".bin"))throw new IOException("草稿不属于当前后台。");if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("草稿文件不能是链接。");if(new FileInfo(path).Length>8000000)throw new IOException("草稿档案超过限制。");var raw=ProtectedData.Unprotect(File.ReadAllBytes(path),Entropy,DataProtectionScope.CurrentUser);return Json.Codec.Deserialize<Dictionary<string,LocalDraft>>(Encoding.UTF8.GetString(raw))??new Dictionary<string,LocalDraft>();}
  public void Save(Dictionary<string,LocalDraft> drafts){NoReparse(Folder,Directory.GetParent(Directory.GetParent(Folder).FullName).FullName);var plain=Encoding.UTF8.GetBytes(Json.Show(drafts));if(plain.Length>6000000)throw new IOException("草稿超过保存大小限制。");var bytes=ProtectedData.Protect(plain,Entropy,DataProtectionScope.CurrentUser);var temp=FilePath+".next-"+Guid.NewGuid().ToString("N");using(var f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(bytes,0,bytes.Length);f.Flush(true);}if(File.Exists(FilePath)){if((File.GetAttributes(FilePath)&FileAttributes.ReparsePoint)!=0)throw new IOException("草稿文件不能是链接。");File.Replace(temp,FilePath,null);}else File.Move(temp,FilePath);}
  public string[] RecoveryFiles(){return Directory.GetFiles(Folder,Prefix+"*.bin").Take(1000).OrderByDescending(File.GetLastWriteTimeUtc).ToArray();}
  public void Dispose(){if(Lease!=null){Lease.Dispose();Lease=null;}}
 }
 public sealed class PendingClientSend {
  public string ProjectId,WorkspaceId,RequestKey,Path,Payload,PayloadHash,State,ResponseJson,OriginalText,ReplyId,CreatedAt;public int AttemptCount;
 }
 public sealed class PendingSendTicket {public PendingClientSend Record;public bool IsNew;}
 public sealed class ClientPendingStore {
  string Folder,FilePath;byte[] Entropy;
  public static bool Tracks(string path){return System.Text.RegularExpressions.Regex.IsMatch(path??"","^/api/workspaces/[A-Za-z0-9-]+/(intent|chat|reply)$");}
  static string Hash(string value){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-","").ToLowerInvariant();}
  static void NoLinks(string path){var d=new DirectoryInfo(path);while(d!=null){if(d.Exists&&(d.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("发送恢复档案目录不能通过链接跳转。");d=d.Parent;}}
  static string ScopeKey(string project,string workspace){if(String.IsNullOrEmpty(project)||String.IsNullOrEmpty(workspace)||project.Length>160||workspace.Length>160)throw new InvalidOperationException("发送缺少准确项目与会话。");return Hash(project+"\n"+workspace);}
  public ClientPendingStore(string config){string full=Path.GetFullPath(config);Folder=Path.Combine(Path.GetDirectoryName(full),"client-pending");NoLinks(Folder);Entropy=Encoding.UTF8.GetBytes(Hash(full.ToLowerInvariant()));FilePath=Path.Combine(Folder,Hash(full.ToLowerInvariant()).Substring(0,24)+".bin");}
  FileStream Lease(){NoLinks(Folder);Directory.CreateDirectory(Folder);NoLinks(Folder);if(File.Exists(FilePath+".lock")&&(File.GetAttributes(FilePath+".lock")&FileAttributes.ReparsePoint)!=0)throw new IOException("发送恢复锁不能是链接。");return new FileStream(FilePath+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);}
  static PendingClientSend Copy(PendingClientSend record){return record==null?null:Json.Codec.Deserialize<PendingClientSend>(Json.Show(record));}
  static PendingClientSend Describe(string path,string payload){
   if(!Tracks(path))throw new InvalidOperationException("不支持的发送恢复路径。");var body=Json.Codec.DeserializeObject(payload);string project=Json.Str(body,"projectId"),workspace=path.Split('/')[3];ScopeKey(project,workspace);
   return new PendingClientSend(){ProjectId=project,WorkspaceId=workspace,Path=path,Payload=payload,PayloadHash=Hash(payload),OriginalText=Json.Str(body,"text"),ReplyId=path.EndsWith("/reply")?Json.Str(body,"messageId"):Json.Str(body,"replyTo")};
  }
  Dictionary<string,PendingClientSend> Read(){
   if(!File.Exists(FilePath))return new Dictionary<string,PendingClientSend>();if((File.GetAttributes(FilePath)&FileAttributes.ReparsePoint)!=0||new FileInfo(FilePath).Length>8000000)throw new IOException("发送恢复档案无效。");
   var plain=ProtectedData.Unprotect(File.ReadAllBytes(FilePath),Entropy,DataProtectionScope.CurrentUser);var all=Json.Codec.Deserialize<Dictionary<string,PendingClientSend>>(Encoding.UTF8.GetString(plain));if(all==null)throw new IOException("发送恢复档案损坏，不创建替代发送。");
   foreach(var pair in all){var r=pair.Value;if(r==null||r.Payload==null||r.Payload.Length>1000000)throw new IOException("发送恢复记录损坏。");var expected=Describe(r.Path,r.Payload);if(r.AttemptCount<0||r.AttemptCount>100000)throw new IOException("发送尝试计数无效。");if(pair.Key!=ScopeKey(r.ProjectId,r.WorkspaceId)||r.ProjectId!=expected.ProjectId||r.WorkspaceId!=expected.WorkspaceId||r.PayloadHash!=Hash(r.Payload)||r.OriginalText!=expected.OriginalText||r.ReplyId!=expected.ReplyId||!System.Text.RegularExpressions.Regex.IsMatch(r.RequestKey??"","^[a-f0-9]{32}$")||!new[]{"PENDING","ACKNOWLEDGED","REJECTED"}.Contains(r.State))throw new IOException("发送恢复记录不匹配，不创建替代发送。");if(r.State!="PENDING"){if(String.IsNullOrEmpty(r.ResponseJson))throw new IOException("发送结果档案缺失。");Json.Codec.DeserializeObject(r.ResponseJson);}}
   return all;
  }
  void Write(Dictionary<string,PendingClientSend> all){
   var plain=Encoding.UTF8.GetBytes(Json.Show(all));if(plain.Length>6000000)throw new IOException("发送恢复档案超过限制，停止本次新发送。");var bytes=ProtectedData.Protect(plain,Entropy,DataProtectionScope.CurrentUser);string temp=FilePath+".next-"+Guid.NewGuid().ToString("N");using(var f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(bytes,0,bytes.Length);f.Flush(true);}if(File.Exists(FilePath)){if((File.GetAttributes(FilePath)&FileAttributes.ReparsePoint)!=0)throw new IOException("发送恢复档案不能是链接。");File.Replace(temp,FilePath,null);}else File.Move(temp,FilePath);
  }
  public PendingClientSend Peek(string project,string workspace){using(Lease()){var all=Read();PendingClientSend old;return all.TryGetValue(ScopeKey(project,workspace),out old)?Copy(old):null;}}
  public PendingSendTicket Prepare(string path,string payload){
   var candidate=Describe(path,payload);using(Lease()){var all=Read();string scope=ScopeKey(candidate.ProjectId,candidate.WorkspaceId);PendingClientSend old;if(all.TryGetValue(scope,out old)){if(old.Path!=path||old.Payload!=payload)throw new InvalidOperationException("本会话有上次发送待核对；当前编辑稿已保留。请先核对原请求，不能复用旧键发送不同正文或接收者。");return new PendingSendTicket(){Record=Copy(old),IsNew=false};}candidate.RequestKey=Guid.NewGuid().ToString("N");candidate.State="PENDING";candidate.CreatedAt=DateTime.UtcNow.ToString("o");all[scope]=candidate;Write(all);return new PendingSendTicket(){Record=Copy(candidate),IsNew=true};}
  }
  public IDisposable AcquireSendLease(PendingClientSend expected){NoLinks(Folder);Directory.CreateDirectory(Folder);NoLinks(Folder);string path=FilePath+".send-"+ScopeKey(expected.ProjectId,expected.WorkspaceId)+".lock";if(File.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("发送操作锁不能是链接。");try{return new FileStream(path,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);}catch(IOException){throw new InvalidOperationException("另一个窗口正在核对本会话的发送；当前草稿已保留，请稍后重新查看。");}}
  public PendingClientSend BeginAttempt(PendingClientSend expected){using(Lease()){var all=Read();PendingClientSend current;if(!all.TryGetValue(ScopeKey(expected.ProjectId,expected.WorkspaceId),out current)||current.RequestKey!=expected.RequestKey||current.Path!=expected.Path||current.PayloadHash!=expected.PayloadHash||current.Payload!=expected.Payload)throw new InvalidOperationException("发送恢复记录已变化，请重新查看原请求；当前草稿未发送。");if(current.State=="PENDING"){if(current.AttemptCount>=100000)throw new IOException("发送核对次数超过限制。");current.AttemptCount++;Write(all);}return Copy(current);}}
  public void RecordResponse(PendingClientSend r,string response,bool rejected){Json.Codec.DeserializeObject(response);using(Lease()){var all=Read();PendingClientSend old;string scope=ScopeKey(r.ProjectId,r.WorkspaceId);if(!all.TryGetValue(scope,out old)||old.RequestKey!=r.RequestKey)return;if(old.State!="PENDING"&&old.ResponseJson!=response)throw new IOException("同一请求出现不同结果，保留待核对记录。");old.State=rejected?"REJECTED":"ACKNOWLEDGED";old.ResponseJson=response;Write(all);}}
  public void Consume(string project,string workspace,string key){using(Lease()){var all=Read();PendingClientSend old;string scope=ScopeKey(project,workspace);if(!all.TryGetValue(scope,out old)||old.RequestKey!=key)return;if(old.State=="PENDING")throw new InvalidOperationException("原API结果仍待核对，不能丢弃请求键或重发。");all.Remove(scope);Write(all);}}
  public static bool ClearRecoveredDraft(PendingClientSend r,string currentPath,string currentPayload,object result){return r.Path==currentPath&&r.Payload==currentPayload&&(!r.Path.EndsWith("/intent")||Json.Str(result,"status")=="EXECUTED")&&Json.Str(result,"status")!="CLIENT_REQUEST_REJECTED";}
 }

 public partial class WorkbenchApp {
  DraftFileStore DraftStore;DispatcherTimer DraftTimer;string DraftProfile,DraftProbe;bool DraftLoading;
  void RequireDurableDraftForSend(){if(DraftStore==null)throw new InvalidOperationException("本机草稿持久化不可用，尚未发送；请先处理草稿存储问题。");SaveCurrentDraft();}
  void RefreshPendingSendUi(){if(CurrentScope==null||String.IsNullOrEmpty(CurrentScope.WorkspaceId)||Client==null)return;try{var pending=Client.PendingSend(CurrentScope.ProjectId,CurrentScope.WorkspaceId);var button=C<Button>("SendButton");button.Content=pending==null?"发送":pending.State=="PENDING"?"核对上次发送":"查看上次发送结果";if(pending!=null){button.IsEnabled=!Sending;button.ToolTip="恢复同一API请求的原始键与正文；不发送当前编辑稿，不要求重发UNKNOWN原生投递。";if(UxMode)C<TextBlock>("IntentStatusText").Text="本会话上次API请求待核对；当前草稿保留。点击上方按钮恢复原请求结果，不创建第二个逻辑发送。";}}catch(Exception ex){C<Button>("SendButton").IsEnabled=false;Note("发送恢复档案无法读取，已阻止新发送："+ex.Message);}}
  void CurrentLogicalSend(out string path,out string payload){path=null;payload=null;if(CurrentScope==null||String.IsNullOrEmpty(CurrentScope.WorkspaceId))return;if(UxMode){path=ScopePath("intent");payload=Json.Show(BuildUxIntentRequest(Composer.Text,ReplyId));}else if(ReplyId==null){path=ScopePath("chat");payload=Json.Show(Scoped("text",Composer.Text,"recipients",Chosen(),"knowledgeRefs",AttachedKnowledge.ToArray()));}else{path=ScopePath("reply");payload=Json.Show(Scoped("messageId",ReplyId,"text",Composer.Text,"recipients",Chosen(),"knowledgeRefs",AttachedKnowledge.ToArray()));}}
  async Task RecoverClientSend(PendingClientSend pending){
   string preview=pending.OriginalText??"";if(preview.Length>320)preview=preview.Substring(0,320)+"…";
   if(MessageBox.Show(Win,"核对上次API请求（当前编辑稿不会发送）\n\n"+preview+"\n\n使用已封存的同一请求键、路径和正文：已有结果则取回；未提交则只恢复原逻辑请求的一次排队。不要求重发原生UNKNOWN投递。当前草稿若有任何变化会保留。继续？","核对上次发送",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;
   RequireDurableDraftForSend();int epoch=Epoch;Sending=true;Composer.IsEnabled=false;C<Button>("SendButton").IsEnabled=false;
   try{var result=await Client.ReplayPending(pending);bool same=epoch==Epoch&&CurrentScope!=null&&CurrentScope.ProjectId==pending.ProjectId&&CurrentScope.WorkspaceId==pending.WorkspaceId;
    if(!same){RequireDurableDraftForSend();Note("原API结果已保存；切回原会话核对。当前会话草稿未发送。");return;}
    string path,payload;CurrentLogicalSend(out path,out payload);bool clear=ClientPendingStore.ClearRecoveredDraft(pending,path,payload,result);
    if(clear){Composer.Clear();ReplyId=null;ReplyBanner.Visibility=Visibility.Collapsed;AttachedKnowledge.Clear();}
    RequireDurableDraftForSend();Client.FinishLogicalSend(pending.ProjectId,pending.WorkspaceId,pending.RequestKey);await RefreshWorkspace();string summary=Json.Str(result,"status")=="CLIENT_REQUEST_REJECTED"?Json.Str(result,"summary"):"原API请求结果已核对；未创建第二个逻辑发送。原生投递若为UNKNOWN仍不重发。";
    if(!clear)summary+=" 当前编辑稿已保留且未发送。";Note(summary);if(UxMode)C<TextBlock>("IntentStatusText").Text=summary;
   }finally{Sending=false;Composer.IsEnabled=true;if(CurrentScope!=null)C<Button>("SendButton").IsEnabled=UxMode||Chosen().Length>0;RefreshPendingSendUi();}
  }

  void SaveCurrentDraft(){if(DraftStore==null||DraftLoading)return;if(CurrentScope!=null&&!String.IsNullOrEmpty(CurrentScope.WorkspaceId))Drafts[CurrentScope.WorkspaceId]=new LocalDraft(){Text=Composer.Text,ReplyId=ReplyId,ReplyText=ReplyText.Text,Knowledge=AttachedKnowledge.ToList()};DraftStore.Save(Drafts);}
  void SetupDraftStore(){try{DraftStore=new DraftFileStore(Root,Config,DraftProfile,NativeMode);Drafts=DraftStore.Load();}catch(Exception ex){if(DraftStore!=null)DraftStore.Dispose();DraftStore=null;Note("草稿自动恢复未启用："+ex.Message+"；当前输入仍保留在本窗口。");}DraftTimer=new DispatcherTimer(){Interval=TimeSpan.FromMilliseconds(500)};DraftTimer.Tick+=(s,e)=>{DraftTimer.Stop();try{SaveCurrentDraft();}catch(Exception ex){Note("草稿保存未完成："+ex.Message);}};Composer.TextChanged+=(s,e)=>{if(DraftLoading)return;DraftTimer.Stop();DraftTimer.Start();};Win.Closing+=(s,e)=>{try{SaveCurrentDraft();}catch(Exception ex){Note("草稿保存未完成："+ex.Message);}DraftTimer.Stop();if(DraftStore!=null)DraftStore.Dispose();};Hook("RestoreDraftButton",()=>{if(DraftStore==null)throw new InvalidOperationException("本机草稿存储未启用。");if(CurrentScope==null||String.IsNullOrEmpty(CurrentScope.WorkspaceId))throw new InvalidOperationException("先选择协作空间。");if(!String.IsNullOrEmpty(Composer.Text))throw new InvalidOperationException("请先保存或处理当前输入，再恢复其他草稿；不会覆盖当前内容。");var candidates=DraftStore.RecoveryFiles().Select(path=>new{Path=path,Data=DraftStore.Load(path)}).Where(x=>x.Data.ContainsKey(CurrentScope.WorkspaceId)&&!String.IsNullOrEmpty(x.Data[CurrentScope.WorkspaceId].Text)).ToArray();if(candidates.Length==0)throw new InvalidOperationException("当前后台/空间没有可恢复草稿。");var dialog=Dialog("恢复本空间工作台草稿",680,330);var p=new StackPanel(){Margin=new Thickness(20)};var choice=new ComboBox(){ItemsSource=candidates.Select(x=>File.GetLastWriteTime(x.Path).ToString("yyyy-MM-dd HH:mm:ss")+" · "+x.Data[CurrentScope.WorkspaceId].Text.Length+" 字").ToArray(),SelectedIndex=0};p.Children.Add(choice);p.Children.Add(new TextBlock(){Text="只恢复当前空间，不读取任何原生Agent输入框；草稿不会自动发送。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,20,0,5)});Accept(dialog,p,"恢复为未发送草稿");dialog.Content=p;if(dialog.ShowDialog()==true){var draft=candidates[choice.SelectedIndex].Data[CurrentScope.WorkspaceId];DraftLoading=true;Composer.Text=draft.Text;ReplyId=draft.ReplyId;ReplyText.Text=draft.ReplyText;AttachedKnowledge=draft.Knowledge??new List<object>();ReplyBanner.Visibility=ReplyId==null?Visibility.Collapsed:Visibility.Visible;DraftLoading=false;SaveCurrentDraft();Note("工作台草稿已恢复，尚未发送。");}return Task.FromResult(0);});}
  async Task ProbeDraft(){await Task.Delay(300);File.WriteAllText(DraftProbe,Json.Show(Json.D("passed",Composer.Text=="虚构第二空间草稿","workspaceId",CurrentScope.WorkspaceId,"draftRestored",Composer.Text=="虚构第二空间草稿","theme",UxThemeName,"autoSent",false,"messageCount",Messages.Items.Count)),Encoding.UTF8);if(Composer.Text!="虚构第二空间草稿")Environment.ExitCode=1;Win.Close();}
 }
}